#include <iostream>

class DynamicArray {
private:
    int* data;
    int size;

public:
    DynamicArray(int s) : size(s) {
        data = new int[size];
        for (int i = 0; i < size; ++i) data[i] = i * 10;
    }

    // Deep Copy Constructor
    DynamicArray(const DynamicArray& other) : size(other.size) {
        data = new int[size];
        for (int i = 0; i < size; ++i) data[i] = other.data[i];
        std::cout << "Deep copy constructor executed." << std::endl;
    }

    ~DynamicArray() {
        delete[] data;
    }
};

int main() {
    DynamicArray arr1(3);
    DynamicArray arr2 = arr1; // Invokes deep copy constructor
    return 0;
}

