#include <iostream>
#include <memory>

class Resource {
public:
    Resource() { std::cout << "Resource Acquired" << std::endl; }
    ~Resource() { std::cout << "Resource Destroyed" << std::endl; }
    void work() { std::cout << "Working..." << std::endl; }
};

int main() {
    std::unique_ptr<Resource> ptr1 = std::make_unique<Resource>();
    ptr1->work();

    // Transfer ownership using std::move()
    std::unique_ptr<Resource> ptr2 = std::move(ptr1);
    if (!ptr1) {
        std::cout << "ptr1 is now null after move." << std::endl;
    }
    ptr2->work();
    return 0;
}

#include <iostream>
#include <memory>

class Node {
public:
    int id;
    Node(int val) : id(val) {}
    ~Node() { std::cout << "Node " << id << " destroyed." << std::endl; }
};

int main() {
    std::shared_ptr<Node> p1 = std::make_shared<Node>(101);
    std::cout << "Ref Count: " << p1.use_count() << std::endl; // 1

    {
        std::shared_ptr<Node> p2 = p1;
        std::cout << "Ref Count inside block: " << p1.use_count() << std::endl; // 2
    }

    std::cout << "Ref Count after block exit: " << p1.use_count() << std::endl; // 1
    return 0;
}

