#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> scores = {85, 92, 78, 95, 60, 88};
    int threshold = 80;

    // Lambda with value capture [threshold]
    int passCount = std::count_if(scores.begin(), scores.end(), [threshold](int score) {
        return score >= threshold;
    });

    std::cout << "Scores >= " << threshold << ": " << passCount << std::endl;
    return 0;
}

