#include <iostream>
#include <stdexcept>

double divide(double a, double b) {
    if (b == 0.0) {
        throw std::runtime_error("Division by zero is undefined.");
    }
    return a / b;
}

int main() {
    try {
        std::cout << "Result: " << divide(10.0, 0.0) << std::endl;
    } catch (const std::runtime_error& e) {
        std::cerr << "Caught Exception: " << e.what() << std::endl;
    }
    return 0;
}

